class _NamedTemporaryFileLike:
    """A binary stream similar to :class:`io.BytesIO` but backed by a
    real, unnamed OS-level temporary file. Unlike ``io.BytesIO``, this
    has a working ``fileno()``, so code under test that passes
    ``sys.stdout``/``sys.stderr`` to APIs like
    :func:`subprocess.run` (which need a real file descriptor) does
    not fail with ``io.UnsupportedOperation``.

    .. versionadded:: 8.2
    """

    def __init__(self) -> None:
        self._file = tempfile.TemporaryFile()

    def write(self, b: ReadableBuffer) -> int:
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        try:
            return self._file.read()
        finally:
            self._file.seek(pos)

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)


